// usecases/sharding/config/config.go:53-67
func (c *Config) validate() error {
	if c.Key != "_id" {
		return errors.Errorf("sharding only supported on key '_id' for now, got: %s", c.Key)
	}
	if c.Strategy != "hash" {
		return errors.Errorf("sharding only supported with strategy 'hash' for now, got: %s", c.Strategy)
	}
	if c.Function != "murmur3" {
		return errors.Errorf("sharding only supported with function 'murmur3' for now, got: %s", c.Function)
	}
	return nil
}

